package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamInstrumentsBank2 {
    private const val T = "පෙරදිග, දේශීය හා ලෝක වාද්‍ය භාණ්ඩ වර්ගීකරණය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("හෝන්බොස්ටල්-සැක්ස් ජාත්‍යන්තර වාද්‍ය භාණ්ඩ වර්ගීකරණය අනුව අවනද්ධ බෙර අයත් වන කාණ්ඩය කුමක්ද?", "මෙම්බ්‍රනෝෆෝන් (Membranophones)", "ඉඩියෝෆෝන් (Idiophones)", "කෝඩෝෆෝන් (Chordophones)", "ඒරෝෆෝන් (Aerophones)", "ඇද බැඳි සම් පටලයක් කම්පනය වීමෙන් නාද උපදවන බෙර Membranophones වේ."),
        q("තාලම්පට, ඝණ්ඨාරය හා ගෙජ්ජි වැනි ඝන වාද්‍ය භාණ්ඩ ජාත්‍යන්තරව හඳුන්වන නාමය කුමක්ද?", "ඉඩියෝෆෝන් (Idiophones)", "මෙම්බ්‍රනෝෆෝන් (Membranophones)", "ඒරෝෆෝන් (Aerophones)", "ඉලෙක්ට්‍රොෆෝන් (Electrophones)", "භාණ්ඩයේම ඝන ද්‍රව්‍ය කම්පනයෙන් නාද උපදවන භාණ්ඩ Idiophones නම් වේ."),
        q("විදුලි තරංග හා පරිපථ මගින් නාද උපදවන ඕගන්, සින්තසයිසර් වැනි භාණ්ඩ ජාත්‍යන්තරව හඳුන්වන්නේ කෙසේද?", "ඉලෙක්ට්‍රොෆෝන් (Electrophones)", "ඉඩියෝෆෝන් (Idiophones)", "කෝඩෝෆෝන් (Chordophones)", "ඒරෝෆෝන් (Aerophones)", "නූතන වර්ගීකරණයේ පස්වන කාණ්ඩය ලෙස විදුලි වාද්‍ය හෙවත් Electrophones එක් කර ඇත."),
        q("භාරතීය හා දේශීය වාද්‍ය වෘන්දයන්හිදී 'තම්බුරාව' නිපදවන සුසර නාදය මගින් සිදුවන ප්‍රධාන මෙහෙය කුමක්ද?", "සම්පූර්ණ වාදනය පුරා මූලික ස්වර පදනම රැකගැනීම", "වේගවත් තාල අඩව් වැයීම", "බෙර පද උච්චාරණය කිරීම", "විශාල ශබ්දයකින් සෙසු භාණ්ඩ යටපත් කිරීම", "රාගයක් ගයන හෝ වයන තාක්කල් ස්ථිර ෂඩ්ජ ආධාරකය පවත්වා ගැනීම තම්බුරාවේ කාර්යයයි."),
        q("තම්බුරාව වාදනය කිරීමේදී තන්තු පිරිමදින නිවැරදි ඇඟිලි පිළිවෙළ කුමක්ද?", "මැදඟිල්ලෙන් පළමු තන්තුවද දබරැඟිල්ලෙන් අනෙක් තන්තුද වැයීම", "මහපටැඟිල්ලෙන් පමණක් සියලු තන්තු ඇදීම", "සියලු ඇඟිලි එකවර තද කිරීම", "මිස්රාබ් හා ගජය භාවිතයෙන් ඇදීම", "පළමු පංචම තන්තුව මැදඟිල්ලෙන්ද ඉතිරි තන්තු තුන දබරැඟිල්ලෙන්ද ලයට පිරිමදී."),
        q("පුරුෂ තම්බුරාව හා ස්ත්‍රී තම්බුරාව අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "ප්‍රමාණය හා කම්පන දිග වෙනස් වීම", "තන්තු ගණන 4ක් සහ 8ක් වීම", "එකක් සුසිර භාණ්ඩයක් වීම", "තුම්බාවක් නොමැති වීම", "පුරුෂ කටහඬේ පහළ ස්වර සඳහා දිගින් වැඩි පුරුෂ තම්බුරාවද, ස්ත්‍රී කටහඬට කුඩා තම්බුරාවද ගනී."),
        q("සිතාරයක දණ්ඩ මත පිහිටි ලෝහ පර්දා සාමාන්‍යයෙන් කීයක් පමණ තිබේද?", "16 සිට 20 දක්වා", "2 ක් පමණි", "50 කට වැඩි ගණනක්", "4 ක් පමණි", "සප්තක දෙකහමාරක පමණ ස්වර ආවරණය වන සේ සිතාරයේ පර්දා 16ත් 20ත් අතර ගණනක් ඇත."),
        q("සිතාරයක ප්‍රධාන තන්තු (බාජ්, ජෝඩි ආදිය) ගණන සාමාන්‍යයෙන් කීයක් පමණ වේද?", "7 ක්", "2 ක්", "18 ක්", "12 ක්", "ප්‍රධාන වාදන තන්තු 7ක් හා ඊට යටින් තරබ් තන්තු 11-13ක් පමණ සිතාරයේ පිහිටයි."),
        q("සිතාරය වාදනය කිරීමේදී මිස්රාබ් භාවිතයෙන් පහළට හා ඉහළට පහර දෙන පද මොනවාද?", "දා (Da) සහ රා (Ra)", "තා (Ta) සහ ධි (Dhi)", "සා (Sa) සහ රි (Ri)", "නා (Na) සහ ගේ (Ge)", "ඇතුළට දෙන පහර 'දා' ලෙසත් පිටතට දෙන පහර 'රා' ලෙසත්, දෙකේ සංයෝගය 'දිරි' ලෙසත් හැඳින්වේ."),
        q("සිතාරය හා සරෝද් යන වාද්‍ය භාණ්ඩ දෙකේ වාදන උපක්‍රම අතර ඇති සමානකම කුමක්ද?", "වම් අතින් ස්වර ඇල්ලීම හා දකුණු අතින් තන්තු කම්පනය", "දෙකෙහිම ගජය භාවිත කිරීම", "දෙකම සුසිර භාණ්ඩ වීම", "දෙකෙහිම මයිනහම තිබීම", "සිතාරයේ මිස්රාබයද සරෝදයේ ජවා (පොල්කටු පතුර) දකුණු අතට ගෙන තන්තු වයයි."),
        q("සරෝද් වාද්‍ය භාණ්ඩය වැයීමට භාවිත කරන පොල්කටු හෝ අස්ථි කැබැල්ල හඳුන්වන්නේ කුමන නමින්ද?", "ජවා (Jawa)", "මිස්රාබ්", "ගජය", "කඩිප්පුව", "සරෝදයේ තන්තු පිරිමැදීමට ත්‍රිකෝණාකාර ජවා නම් ප්ලෙක්ට්‍රමය යොදාගනී."),
        q("සාරංගිය වැයීමේදී වාදකයා තන්තු මත තද කර ස්වර මතු කරගන්නේ ඇඟිලිවල කවර කොටසින්ද?", "වම් අතේ නියපොතු පිටුපස මුල් කොටසින්", "දකුණු අතේ මහපටැඟිලි තුඩෙන්", "ලී මිටියක ආධාරයෙන්", "ලෝහ මුදුවක ආධාරයෙන්", "සාරංගියේ තන්තු මත ඇඟිලි තුඩු නොතබා නියපොතු ආසන්න සම පැත්ත තද කර ස්වර අල්ලයි."),
        q("ගජයෙන් වයන භාරතීය තත වාද්‍ය අතර හඬ පැහැදිලිව මිනිස් කටහඬට ඉතා සමීප යැයි පිළිගන්නා භාණ්ඩය කුමක්ද?", "සාරංගිය", "සන්තූරය", "සිතාරය", "තම්බුරාව", "සාරංගිය මිනිස් කටහඬේ සියුම් භාව හා ගමක ඉතා නිවැරදිව අනුකරණය කරන භාණ්ඩයයි."),
        q("එස්රාජ් සහ දිල්රුබා යන වාද්‍ය භාණ්ඩ දෙකෙහිම වාදන ලක්ෂණය කුමක්ද?", "පර්දා ඇති අතර ගජයෙන් වාදනය කිරීම", "පර්දා නැති අතර මිස්රාබයෙන් වැයීම", "මයිනහමකින් සුළං සැපයීම", "බෙර සම මත කඩිප්පුවෙන් ගැසීම", "සිතාරය මෙන් පර්දා තිබුණද එස්රාජ් හා දිල්රුබා වයනු ලබන්නේ ගජය මගිනි."),
        q("ගජයේ අශ්ව කෙඳි මත තන්තු ලිස්සා නොයා නිසි ඝර්ෂණය ඇති කිරීමට ආලේප කරන ද්‍රව්‍යය කුමක්ද?", "රෝසින් (Rosin / දුම්මල මිශ්‍රණය)", "පොල් තෙල්", "ජලය හා සබන්", "යකඩ කුඩු", "ගජයේ කෙඳි තන්තුවල නිසි ලෙස ඇලී කම්පනය වීමට රෝසින් ආලේප කෙරේ."),
        q("තබ්ලාවේ දායා හි උඩ දාරය වටා පිහිටි තුනී පිටත සම් කොටස හඳුන්වන නාමය කුමක්ද?", "චාන්ටි (කිනාර්)", "සියාහි", "මෛදාන්", "බද්දි", "ගජ්රා අසලින්ම ඇති වටේ සිහින් සම් දාරය චාන්ටි හෙවත් කිනාර් ලෙස හැඳින්වේ."),
        q("තබ්ලාවේ දායා හි 'නා' හෝ 'තා' යන තීව්‍ර ස්වර බෝලය වැයෙන්නේ කවර ස්ථානයක ඇඟිලි ගැසීමෙන්ද?", "චාන්ටි (කිනාර්) ප්‍රදේශයේ", "සියාහි මැදම", "බායා හි පතුලේ", "බද්දි පටිය මත", "දායා හි චාන්ටි කොටසට දබරැඟිල්ලෙන් පහර දීමෙන් පැහැදිලි 'නා' හෝ 'තා' නාදය උපදී."),
        q("තබ්ලාවේ 'තින්' (Tin) නැමැති අක්ෂරය වාදනය කරන්නේ දායා හි කවර ස්ථානයකට පහර දීමෙන්ද?", "මෛදාන් (ලව්) කොටසට", "සියාහි මැදට තදින්", "ගජ්රා කොටසට", "බායා හි දාරයට", "මෛදාන් ප්‍රදේශයේ දබරැඟිල්ලෙන් නිදහස් පහරක් දීමෙන් 'තින්' නාදය ලබාගනී."),
        q("තබ්ලාවේ සුසර පරීක්ෂා කිරීමේදී හා 'සූර්' කිරීමට පාවිච්චි කරන කුඩා උපකරණය කුමක්ද?", "තබ්ලා මිටිය (හතෝඩි)", "කඩිප්පුව", "ගජය", "ජවා", "ගජ්රා වටා මෘදුව තට්ටු කරමින් සහ ගට්ටා සීරුමාරු කරමින් සුසර කිරීමට හතෝඩිය ගනී."),
        q("තබ්ලා භාවිතයට පෙර බෙර සම මතුපිට තෙතමනය හා ඇලෙන සුළු බව අඩු කිරීමට ඉසින සුදු පැහැති කුඩු වර්ගය කුමක්ද?", "ටැල්කම් පවුඩර්", "යකඩ කුඩු", "ලුණු කුඩු", "වැලි කැට", "ඇඟිලි සුමටව සම මත ගමන් කිරීමට සහ දහඩිය උරාගැනීමට පවුඩර් ස්වල්පයක් යොදයි."),
        q("තබ්ලාවේ දායා හා බායා යන දෙකෙහිම කේන්ද්‍රීය බඳ වටා ඇදී යන දිග සම් පටිය හඳුන්වන්නේ කුමන නමින්ද?", "බද්දි (Baddi)", "මෛදාන්", "සියාහි", "චුම්බල", "ඉහළ ගජ්රා සහ පහළ ආධාරක වළල්ල අතර සිග්සැග් ආකාරයට ඇද ඇති සම් පටිය බද්දි නම් වේ."),
        q("දේශීය හා කර්ණාටක සංගීතයේදී දකුණු ඉන්දීය ශාස්ත්‍රීය ප්‍රසංගවල ප්‍රධාන තාල භාණ්ඩය කුමක්ද?", "මෘදංගම්", "තබ්ලාව", "තම්මැට්ටම", "උඩැක්කිය", "තබ්ලාව හින්දුස්ථානි සංගීතයේදී මෙන්ම කර්ණාටක සංගීතයේ ප්‍රධාන තාල භාණ්ඩය මෘදංගම්ය."),
        q("උඩරට ගැටබෙරයේ දෙකෙළවරට සාපේක්ෂව මැද කොටසේ ඇති සුවිශේෂී හැඩය කුමක්ද?", "මැද කොටස මහත් වී දෙපසට ක්‍රමයෙන් සිහින් වීම", "සම්පූර්ණයෙන් එක සමාන සිලින්ඩරාකාර වීම", "මැද කොටස ඉතා සිහින් වීම", "එක් කෙළවරක් සම්පූර්ණයෙන් වැසී තිබීම", "ගැටබෙරයේ මැද මහත් වී දෙපස බෙර ඇස් දෙසට ක්‍රමයෙන් පටු වන ස්වරූපයක් ඇත."),
        q("ගැටබෙරයේ දෙකෙළවර ඇස් දෙක සම්බන්ධ කර තද කිරීමට යොදාගන්නා සම් පටි හඳුන්වන්නේ කුමන නමින්ද?", "වරපට", "ගට්ටා", "සියාහි", "කැපුම් පටි", "බෙර ඇස් දෙකේ වෙනිවැල් ගැට සහ සම් පටි හරහා ඇදී යන දිග සම් පටි වරපට නම් වේ."),
        q("ගැටබෙරයේ බෙර ඇස වටා වූ ගැට රවුම හෙවත් දාරය හඳුන්වන්නේ කුමන නමින්ද?", "කැපුම් හම / වෙනිවැල් කැරැල්ල", "සියාහි", "බායා", "චාන්ටි", "බෙර සම ශක්තිමත්ව රඳවා තබාගැනීමට ගෙතූ කැපුම් හම හා වරපට යොදාගනී."),
        q("දේශීය ගැටබෙරය හා පහතරට යක්බෙරය සංසන්දනය කිරීමේදී යක්බෙරයේ බඳේ ස්වභාවය කුමක්ද?", "එක සමාන විෂ්කම්භයකින් යුත් සිලින්ඩරාකාර බඳක් වීම", "මැද ඉතා මහත් බඳක් වීම", "මැද ඉතා සිහින් බඳක් වීම", "මැටි කළගෙඩි හැඩයකින් යුක්ත වීම", "යක්බෙරය දිගින් වැඩි සමාන සිලින්ඩරාකාර හැඩයකින් යුක්ත බැවින් දික්බෙරය ලෙසද හැඳින්වේ."),
        q("යක්බෙරයේ බෙර ඇස් දෙක සඳහා සාමාන්‍යයෙන් යොදාගනු ලබන්නේ කවර සතුන්ගේ සම්ද?", "ගව බඩවැල් හෝ තලගොයි/එළු සම්", "වඳුරු සම පමණක්", "කිඹුල් සම", "සිංහ සම", "යක්බෙර ඇස්වලට බොහෝ විට තලගොයි සම හෝ ගව ආමාශ පටල (බොකු සම) යොදයි."),
        q("සබරගමු දවුලේ බෙර ඇස් දෙකෙහි විශාලත්වය පවතින්නේ කෙසේද?", "ගැටබෙරයට වඩා තරමක් විශාලව හා මහත්ව", "ඉතා කුඩාවට උඩැක්කිය මෙන්", "එක් පැත්තක් සම්පූර්ණයෙන් වසා", "ත්‍රිකෝණාකාර හැඩයකින්", "කොට හා මහත් සිලින්ඩරාකාර බඳක් ඇති දවුලේ මුහුණත් දෙක ප්‍රමාණයෙන් විශාලය."),
        q("දවුල වාදනය කිරීමේදී දකුණු අතට හෝ වම් අතට කුඩා කෝටුවක් ගෙන වයන්නේ කෙසේද?", "වම් අතින් සහ දකුණු අතේ ඇති කඩිප්පුවෙන්", "දෙපසම කඩිප්පු දෙකකින්", "දෙපසම ඇඟිලිවලින් පමණක්", "මිටියකින් ගැසීමෙන්", "දවුලේ වම් ඇස අතින්ද දකුණු ඇස කඩිප්පුවෙන්ද වයන නිසා එය විතතාතත ගණයට වැටේ."),
        q("හේවිසි වාදනයේදී තම්මැට්ටම් වාදකයා බෙරය තම ඉණෙහි බැඳගෙන කුමන ඉරියව්වකින් වයයිද?", "සිටගෙන හෝ ගමන් කරමින්", "බිම වැතිරීගෙන", "හිස මත තබාගෙන", "උරහිසේ එල්ලා නොගෙන බිම තබා පමණක්", "පෙරහැර හා හේවිසි මණ්ඩපයේදී තම්මැට්ටම ඉණෙහි බැඳ කඩිප්පු දෙකෙන් වයයි."),
        q("දේශීය හොරණෑවේ පිහිටි ස්වර විවර (ඇඟිලි තබන සිදුරු) ගණන සාමාන්‍යයෙන් කීයද?", "7 ක් හෝ 8 ක්", "2 ක් පමණි", "24 ක්", "1 ක් පමණි", "කිහිප දිගැති හොරණෑ දණ්ඩේ ස්වර 7ක් පමණ ඇල්ලීමට ඇඟිලි සිදුරු සාදා ඇත."),
        q("දේශීය හොරණෑව වාදනය කරන ශිල්පියා අඛණ්ඩව නොනවත්වා පිඹීම සඳහා යොදාගන්නා විශේෂ ශ්වසන ක්‍රමය කුමක්ද?", "චක්‍රීය ශ්වසනය (Circular Breathing)", "වේගවත් කෙටි හුස්ම ගැනීම", "හුස්ම ගැනීම සම්පූර්ණයෙන් නතර කිරීම", "මයිනහමකින් හුළං දීම", "කම්මුල්වල රැඳවූ වාතය පිඹින අතරම නාසයෙන් හුස්ම ගැනීමේ චක්‍රීය ශ්වසනය යොදාගනී."),
        q("භාරතීය ෂැහනායි වාද්‍ය භාණ්ඩය ලෝක ප්‍රසිද්ධියට පත් කළ මහා කලාකරුවා කවුද?", "උස්තාද් බිස්මිල්ලා ඛාන්", "පණ්ඩිත් රවි ශංකර්", "පණ්ඩිත් හරිප්‍රසාද් චෞරාසියා", "උස්තාද් අම්ජඩ් අලි ඛාන්", "භාරත රත්න උස්තාද් බිස්මිල්ලා ඛාන් ෂැහනායි වාදනය ශාස්ත්‍රීය වේදිකාවට ගෙන ආවේය."),
        q("බන්සූරි (උණ බට නළා) වාදනයෙන් ලෝක ප්‍රකට වූ භාරතීය සංගීතවේදියා කවුද?", "පණ්ඩිත් හරිප්‍රසාද් චෞරාසියා", "උස්තාද් සාකීර් හුසේන්", "පණ්ඩිත් ශිව්කුමාර් ශර්මා", "උස්තාද් බිස්මිල්ලා ඛාන්", "පණ්ඩිත් හරිප්‍රසාද් චෞරාසියා සහ පන්නාලාල් ඝෝෂ් බන්සූරි වාදනයේ මහැදුරන් වේ."),
        q("සන්තූරය වාදනය කිරීම ලෝකය පුරා ජනප්‍රිය කළ ප්‍රවීණ භාරතීය කලාකරුවා කවුද?", "පණ්ඩිත් ශිව්කුමාර් ශර්මා", "පණ්ඩිත් රවි ශංකර්", "උස්තාද් බිස්මිල්ලා ඛාන්", "පණ්ඩිත් ජස්රාජ්", "කාශ්මීර ජන භාණ්ඩයක් වූ සන්තූරය ශාස්ත්‍රීය සංගීතයට එක් කළේ පණ්ඩිත් ශිව්කුමාර් ශර්මාය."),
        q("සරෝද් වාදනයෙන් භාරතීය ශාස්ත්‍රීය සංගීතය බැබළවූ විශිෂ්ට වාදකයෙකු කවුද?", "උස්තාද් අම්ජඩ් අලි ඛාන් (හෝ අලි අක්බර් ඛාන්)", "පණ්ඩිත් හරිප්‍රසාද් චෞරාසියා", "උස්තාද් බිස්මිල්ලා ඛාන්", "පණ්ඩිත් බීම්සේන් ජෝෂි", "උස්තාද් අලි අක්බර් ඛාන් සහ උස්තාද් අම්ජඩ් අලි ඛාන් සරෝද් වාදනයේ මහාචාර්යවරු වෙති."),
        q("සිතාරය බටහිර ලෝකයට පවා හඳුන්වා දුන් භාරතීය මහා සිතාර් වාදකයා කවුද?", "පණ්ඩිත් රවි ශංකර්", "උස්තාද් සාකීර් හුසේන්", "පණ්ඩිත් ශිව්කුමාර් ශර්මා", "උස්තාද් රෂීඩ් ඛාන්", "පණ්ඩිත් රවි ශංකර් හා උස්තාද් විලායත් ඛාන් සිතාර් වාදනයේ අග්‍රගණ්‍ය ශිල්පීන් වේ."),
        q("ඉන්දියාවේ සුප්‍රසිද්ධ තබ්ලා වාදක උස්තාද් අල්ලා රක්ඛාගේ සුවිශේෂී කුසලතාව කුමක්ද?", "සංකීර්ණ තාල පද නිර්මාණය හා ලයකාරී වාදනය", "වයලීන ගජයෙන් සිතාරය වැයීම", "බන්සූරිය නිපදවීම", "හාමෝනියමය සොයාගැනීම", "උස්තාද් අල්ලා රක්ඛා තබ්ලාව ඒකල වාද්‍ය භාණ්ඩයක් ලෙස ලොව පුරා ජනප්‍රිය කළේය."),
        q("මහ රබාන (බැංකු රබාන) සාදන ක්‍රමයේදී රබන් රාමුව සඳහා බහුලව යොදාගන්නා දැවය කුමක්ද?", "කොස් හෝ ඇහැල/ගන්සූරිය දැව", "වියළි උණ පතුරු", "වියළි ලබු කබල්", "කිතුල් කොළ", "විශාල වෘත්තාකාර රාමුව ශක්තිමත්ව තැනීමට කොස් හෝ මිල්ල දැව භාවිත කෙරේ."),
        q("රබාන වැයීමට පෙර බෙර සම තද කර සුසර නාදයක් ගැනීම සඳහා ගැමියන් කරන සාම්ප්‍රදායික ක්‍රියාව කුමක්ද?", "ගිනි රස්නයට අල්ලා රත් කිරීම", "ජලයේ ගිල්වා තැබීම", "පොල් තෙල් ආලේප කිරීම", "ගට්ටා මිටියෙන් තට්ටු කිරීම", "මෘදු ගිනි දැල්ලකින් හෝ අඟුරු රස්නයෙන් රබන් සම රත් කළ විට තෙතමනය ඉවත්ව සම තද වේ."),
        q("ශ්‍රී ලංකාවේ ශාන්තිකර්ම අතර දෙවොල් මඩු හා ගම්මඩු වලදී යක්බෙරය හා සමානව භාවිත කරන කුඩා ඝන වාද්‍ය භාණ්ඩය කුමක්ද?", "කයිතාලම / තාලම්පට", "ජල්තරංග", "සන්තූරය", "ගිටාරය", "පහතරට නැටුම් හා යාග කර්මවලදී යක්බෙරය සමඟ කුඩා පිත්තල තාලම්පට වාදනය කෙරේ."),
        q("ශ්‍රී ලංකාවේ ජන සංගීතයේ හා පන්සල් පෙරහැරවල 'කොම්බුව' යනුවෙන් හඳුන්වනු ලබන්නේ කුමන වර්ගයේ භාණ්ඩයක්ද?", "C හෝ S හැඩැති පිත්තල සුසිර නළාවක්", "මැටි බෙරයක්", "ලී තාලම්පටක්", "තන්තු 4ක වීණාවක්", "පිත්තලෙන් තැනූ වක්‍ර හැඩැති කොම්බුව පෙරහැරවලදී නාද නංවන සුසිර භාණ්ඩයකි."),
        q("උත්තර භාරතීය හා කර්ණාටක සංගීතයේ ගායනා සඳහා පහසු වන ලෙස ඩිජිටල්කරණය කළ 'ඉලෙක්ට්‍රොනික් තම්බුරාව' සපයන්නේ කුමක්ද?", "නිවැරදි සුසර කරන ලද ප - ස - ස - මන්ද්‍ර ස නාදය", "වේගවත් තබ්ලා තාල රටා පමණක්", "සිතාර් ගත් සංගීතය", "සමූහ ගායනා හඬ", "තම්බුරාව නොමැති අවස්ථාවලදී ඕනෑම ශ්‍රැතියකට සකස් කළ හැකි ඉලෙක්ට්‍රොනික් තම්බුරාව භාවිත වේ."),
        q("වාද්‍ය වෘන්දයක (Orchestra) 'සංධ්වනි' හෙවත් Harmonic සංයෝජනයක් පහසුවෙන් වැයිය හැකි බටහිර භාණ්ඩයක් වන්නේ කුමක්ද?", "පියානෝව (හෝ ගිටාරය)", "බන්සූරිය", "තබ්ලාව", "හොරණෑව", "යතුරු පුවරුවේ එකවර ස්වර කිහිපයක් එබිය හැකි නිසා පියානෝව හා ගිටාරය කෝඩ්ස් (Chords) වැයීමට සුදුසුය."),
        q("බටහිර පියානෝවක සම්පූර්ණ සම්මත යතුරු පුවරුවේ ඇති මුළු යතුරු ගණන කීයද?", "88 කි", "32 කි", "12 කි", "108 කි", "සම්මත ග්‍රෑන්ඩ් සහ අප්‍රයිට් පියානෝවක සුදු යතුරු 52ක් හා කළු යතුරු 36ක් ඇතුළුව යතුරු 88ක් ඇත."),
        q("දකුණු ඉන්දීය කර්ණාටක සංගීතයේ ඝන වාද්‍ය අතර සුප්‍රසිද්ධ 'මෝර්සිං' (Morsing) හෙවත් මුඛ වීණාව වයන්නේ කෙසේද?", "දත් අතර තබා ඇඟිල්ලෙන් යකඩ කටුව කම්පනය කිරීමෙන්", "කඩිප්පු දෙකකින් තට්ටු කිරීමෙන්", "ගජයකින් පිරිමැදීමෙන්", "තොල්වලින් දිගටම පිඹීමෙන්", "මුඛ කුහරය අනුනාද පෙට්ටිය ලෙස භාවිත කර දිව හා ඇඟිල්ලෙන් මෝර්සිං වයයි."),
        q("කර්ණාටක සංගීතයේ රිද්ම වාදනයට ගන්නා කුඩා එක්පසෙක උරග සමක් යෙදූ රාමු බෙරය කුමක්ද?", "කංජිරා (Kanjira)", "මද්දලය", "දවුල", "තම්මැට්ටම", "වටේට කුඩා තහඩු කැබැල්ලක් සහිත තනි අතින් වයන කංජිරා දකුණු ඉන්දීය භාණ්ඩයකි."),
        q("ඉන්දීය හා ශ්‍රී ලාංකේය ජන සංගීතයේ කුඩා ප්‍රමාණයේ සම් බෙරයක් වන 'ඩමරුව' වැයීමේදී නාදය උපදින්නේ කෙසේද?", "මැද බැඳි නූල්වල ඇති ගැට දෙක දෙපස සම් මත වැදීමෙන්", "ලී මිටියකින් ගැසීමෙන්", "සුළඟ පිඹීමෙන්", "තන්තු ඇදීමෙන්", "මැණික් කටුව දෙපසට කරකවන විට එල්ලා ඇති බෝල ගැට සම් පටල දෙකේ ගැටී හඬ නැගේ."),
        q("බටහිර සිම්ෆනි වාද්‍ය වෘන්දයක වයලීනයට වඩා විශාල, ගැඹුරු මන්ද්‍ර හඬක් දෙන බිම තබා වයන භාණ්ඩය කුමක්ද?", "චෙලෝ (Cello)", "පිකොලෝ (Piccolo)", "ෆ්ලූට් (Flute)", "ට්‍රයන්ගල් (Triangle)", "වයලීන් පවුලේ විශාල භාණ්ඩයක් වන චෙලෝව වාදකයා පාද දෙක අතර බිම තබා ගජයෙන් වයයි."),
        q("බටහිර සංගීතයේ සෑම ප්‍රධාන තාල භාණ්ඩ පවුලටම අයත් නොවන, තනි ස්වරයකට සුසර කළ හැකි විශාල තඹ බෙර මොනවාද?", "ටිම්පනි (Timpani / Kettle drums)", "සිම්බල්ස්", "මරකාස්", "බොංගෝ", "කකුලේ පැඩලයක් ආධාරයෙන් ස්වර වෙනස් කළ හැකි ටිම්පනි බෙර බටහිර වාද්‍ය වෘන්දයේ වැදගත් වේ."),
        q("ශ්‍රී ලංකාවේ බටහිර ක්‍රිස්තියානි දේවස්ථානවල බහුලව භාවිත කෙරෙන යතුරු පුවරු සුසිර භාණ්ඩය කුමක්ද?", "පයිප් ඕගනය (Pipe Organ)", "සිතාරය", "තම්බුරාව", "සන්තූරය", "විවිධ ප්‍රමාණයේ ලෝහ නළා තුළට වාතය යවා වයන පයිප් ඕගනය පල්ලි සංගීතයේ ප්‍රධාන වේ."),
        q("ශ්‍රී ලංකාවේ 'මහා කලා මංගල්‍ය' හා සාම්ප්‍රදායික විවාහ උත්සවවල 'ජයමංගල ගාථා' ගායනය සමඟ ඇතැම් විට වයන මංගල භාණ්ඩය කුමක්ද?", "හක්ගෙඩිය හෝ පංචතූර්ය භාණ්ඩ", "ඩ්‍රම් සෙට් එක", "ඉලෙක්ට්‍රික් ගිටාරය", "සැක්සෆෝනය", "මංගල අවස්ථාවලදී සෙත් පැතීම සඳහා හක්ගෙඩිය හා මගුල් බෙර වාදනය සාම්ප්‍රදායිකව සිදු වේ."),
        q("හින්දුස්ථානි සංගීතයේදී 'පක්වාජ්' හා 'තබ්ලා' අතර ඇති ඓතිහාසික සම්බන්ධය කුමක්ද?", "පඛාවජය දෙකට වෙන් වී තබ්ලාව බිහිවූ බව සැලකීම", "තබ්ලාව දෙකට වෙන් වී පඛාවජය බිහිවීම", "දෙකම සුසිර භාණ්ඩ වීම", "දෙකම බටහිරින් පැමිණීම", "ජනප්‍රවාදයට අනුව පඛාවජය දෙකඩ වී දායා සහ බායා ලෙස තබ්ලාව බිහිවූ බව පැවසේ."),
        q("උත්තර භාරතීය හින්දුස්ථානි සංගීතයේ 'ෂැහනායි' හා දකුණු ඉන්දීය කර්ණාටක සංගීතයේ ඊට සමාන භාණ්ඩය කුමක්ද?", "නාදස්වරම් (Nadaswaram)", "සරස්වතී වීණාව", "ඝටම්", "වයලීනය", "දකුණු ඉන්දීය කෝවිල් හා මංගල උත්සවවලදී ෂැහනායි හා සමාන නාදස්වරම් වයයි."),
        q("දේශීය හොරණෑව හා ඉන්දියානු ෂැහනායි අතර ඇති ප්‍රධාන පොදු සමානකම කුමක්ද?", "ද්විත්ව පත්‍රිකාවක් පිඹීමෙන් හඬ නිපදවීම", "දෙකම තන්තු භාණ්ඩ වීම", "දෙකේම සම් පටල තිබීම", "දෙකම ජලය පුරවා වැයීම", "හොරණෑවේ ඉපියාව මෙන්ම ෂැහනායි හි ද්විත්ව බට පත මගින් නාදය උපදවයි."),
        q("චීනයේ සාම්ප්‍රදායික සංගීතයේ එන ද්වි-තන්තු ගජ වාද්‍ය භාණ්ඩය හඳුන්වන්නේ කුමන නමින්ද?", "එර්හු (Erhu)", "බන්සූරිය", "තබ්ලාව", "සිතාරය", "තන්තු දෙකක් අතරින් ගජයේ කෙඳි යවා වයන සුප්‍රකට චීන තත වාද්‍යය එර්හු වේ."),
        q("ඉතාලි හා යුරෝපීය කණ්ඩායම් සංගීතයේ දැකිය හැකි මයිනහමක් හා යතුරු පුවරුවක් සහිත අතේ තබා වයන භාණ්ඩය කුමක්ද?", "ඇකෝඩියනය (Accordion)", "වයලීනය", "සන්තූරය", "තම්බුරාව", "දෙපසට ඇද මයිනහම ක්‍රියා කරවන අතරතුර යතුරු හා බොත්තම් ඔබා ඇකෝඩියනය වයයි."),
        q("අප්‍රිකානු සම්භවයක් ඇති අතර ලෝක ජන සංගීතයේ භාවිත වන ඇඟිලිවලින් ලෝහ තහඩු කිහිපයක් තල්ලු කර වයන භාණ්ඩය කුමක්ද?", "කලිම්බා (Kalimba / Thumb Piano)", "පඛාවජ්", "ෂැහනායි", "ජල්තරංග", "කුඩා ලී පෙට්ටියක් මත සවි කළ ලෝහ පටි මහපටැඟිලිවලින් තට්ටු කර වයන්නේ කලිම්බාය."),
        q("සිතාරයක් සුසර කිරීමේදී පළමුවෙන්ම කළ යුතු මූලික පියවර කුමක්ද?", "වාදකයාගේ හෝ ගායකයාගේ ෂඩ්ජයට (ස) බාජ් හා ජෝඩි තන්තු සුසර කිරීම", "පර්දා සියල්ල ගලවා ඉවත් කිරීම", "මිස්රාබය ලිහිල් කිරීම", "තරබ් තන්තු සියල්ල කැපීම", "සිතාරයේ බාජ් තන්තුව මධ්‍යමයට හා ජෝඩි තන්තු ෂඩ්ජයට මුලින්ම සුසර කෙරේ."),
        q("සිතාරයේ 'තාරගහන්' (Taragahan) නමින් හඳුන්වනු ලබන්නේ කුමන කොටසද?", "තන්තු ඝෝරචය වෙත යාමට පෙර දණ්ඩ ඉහළින් පසු කරන අස්ථි පාලම", "පහළ ඇති ලොකු ලබු ගෙඩිය", "දකුණු අතේ මිස්රාබය", "බඳ පිටුපස ඇති කැටයම", "ඛූන්ටි අසල පිහිටි තන්තු වෙන් කර තබන පළමු පාලම තාරගහන් ලෙස හැඳින්වේ."),
        q("තම්බුරාවක් වාදනය කර අවසන් වූ පසු සුරක්ෂිතව තැබිය යුත්තේ කෙසේද?", "බඳ බිම නොගැටෙන සේ කෙළින් හේත්තු කර හෝ පෙට්ටියේ තැබීම", "බර පොත් ඒ මත ගොඩගැසීම", "තන්තු සියල්ල තදින් ඇද තැබීම", "ජලයෙන් සෝදා තැබීම", "සියුම් ලබු තුම්බාව පිපිරීමෙන් වැළැක්වීමට ප්‍රවේශමෙන් තැන්පත් කළ යුතුය."),
        q("ශ්‍රී ලංකාවේ වයලීන හා තබ්ලා වාද්‍ය ශිල්පීන් ප්‍රසංගයකදී එකිනෙකා සමඟ සම්බන්ධ වන ප්‍රධාන ස්ථානය කුමක්ද?", "සම (තාලයේ පළමු මාත්‍රාව) මත එකවර පැමිණීම", "වෙන වෙනම තමන් කැමති ලයකට වැයීම", "ගායකයා නැවැත්වූ පසු පටන් ගැනීම", "ප්‍රේක්ෂකයන්ගේ අත්පොළසන් නාදය මත", "ගායකයා හෝ සිතාර් වාදකයා තබ්ලා වාදකයා සමඟ සම මත හමුවීමෙන් ලයකාරී සුසංයෝගය ඇති වේ."),
        q("ලී පෙට්ටියක් තුළ තන්තු හෝ ලෝහ දඟර ඇති විද්‍යුත් ගිටාරය සංගීතයට ගෙන ආ ප්‍රධාන වෙනස කුමක්ද?", "ශබ්ද වර්ධක හරහා ඉහළ හඬක් හා විවිධ නාද ප්‍රයෝග ලබාදීම", "තන්තු නොමැතිව සුළඟින් වැයීම", "තම්බුරාව වෙනුවට ආදේශ වීම", "සියාහි ආලේප කිරීමට හැකි වීම", "පික්-අප් (Pickups) මගින් තන්තු කම්පනය විද්‍යුත් සංඥා බවට හරවා ඇම්ප්ලිෆයරයට යවයි."),
        q("සිංහල සාම්ප්‍රදායික බෙර කර්මාන්තයේදී 'බෙර කඳ' හෑරීමෙන් පසු එහි කල්පැවැත්මට කරන ප්‍රධාන පිළියම කුමක්ද?", "පදම් කර වියළා තෙල් හෝ ලාක්ෂා ආලේප කිරීම", "දියේ ගිල්වා තැබීම", "යකඩ ඇණ ගැසීම", "තීන්ත වර්ග දහයක් ගෑම", "ලීය පිපිරීම හා කෘමි හානි වැළැක්වීමට දැව පදම් කර ස්වාභාවික ආලේප ගල්වයි."),
        q("බෙර වර්ග සෑදීමේදී දකුණු සහ වම් බෙර ඇස් දෙකේ ස්වරය වෙනස් වීමට බලපාන භෞතික සාධක මොනවාද?", "සමේ ඝනකම, ඇසේ විෂ්කම්භය හා වරපට ආතතිය", "බෙරයේ වර්ණය පමණක්", "වාදකයාගේ උස හා බර", "කඩිප්පුවේ වර්ණය", "පටු ඇස හා තද සම උස් හඬද, පුළුල් ඇස හා බුරුල් සම ගැඹුරු හඬද නිපදවයි."),
        q("සංගීත ශාලාවක හෝ ගුවන්විදුලි මැදිරියක 'බැලන්ස් කිරීම' (Balancing) යනුවෙන් අදහස් කරන්නේ කුමක්ද?", "ගායන හා සියලු වාද්‍ය භාණ්ඩවල හඬ සමබර මට්ටමක තැබීම", "වාද්‍ය භාණ්ඩ සියල්ල බර කිරා බැලීම", "ප්‍රේක්ෂකයන් දෙපැත්තට බෙදා තැබීම", "ගායකයාගේ හඬ සම්පූර්ණයෙන් වැසීම", "තනි භාණ්ඩයක ඝෝෂාවෙන් අනෙක් භාණ්ඩ හා ගායනය නොවැසෙන සේ ශබ්දය පාලනය කිරීමයි."),
        q("දේශීය හේවිසි වාදනයට අයත් 'තේවා හේවිසි', 'පූජා හේවිසි' සහ 'ගමන් හේවිසි' සඳහා පොදුවේ ගන්නා භාණ්ඩ කට්ටලය කුමක්ද?", "දවුල්, තම්මැට්ටම්, හොරණෑ හා තාලම්පට", "වයලීන්, ගිටාර්, සිතාර් හා තබ්ලා", "උඩැක්කි හා බුම්මැඩි පමණක්", "පියානෝ හා සැක්සෆෝන්", "බෞද්ධ වත්පිළිවෙත් හා පෙරහැරවලදී මෙම සාම්ප්‍රදායික හේවිසි කට්ටලය භාවිත කෙරේ."),
        q("ශ්‍රී ලංකාවේ 'මඟුල් බෙර' වාදනය සඳහා සම්ප්‍රදායානුකූලව භාවිත කරන ප්‍රධාන බෙරය කුමක්ද?", "ගැටබෙරය (උඩරට) හෝ යක්බෙරය (පහතරට)", "බොංගෝ බෙරය", "ජෑස් ඩ්‍රම් සෙට් එක", "කොංගා බෙරය", "සුබ කටයුතු හා කලා උත්සව ආරම්භයේදී ත්‍රිවිධ රත්නය නමස්කාර කරමින් මඟුල් බෙර වැයේ."),
        q("මිශ්‍ර වාද්‍ය වෘන්දයක (Fusion Orchestra) පෙරදිග සිතාරය සමඟ බටහිර චෙලෝ හෝ ෆ්ලූට් එක් කිරීමෙන් ලැබෙන ප්‍රතිඵලය කුමක්ද?", "විවිධ සංගීත වර්ණ හා ගැඹුරු හාමනි රසයක් එක්වීම", "පෙරදිග ස්වර 7 නැති වී යාම", "රාගය සම්පූර්ණයෙන් විකෘති වීම", "තාලය අහෝසි වී යාම", "පෙර-අපර දෙදිගම භාණ්ඩ ශිල්පීයව මුසු කිරීමෙන් සමෘද්ධිමත් නාද වර්ණයක් බිහිවේ."),
        q("බටහිර වාද්‍ය භාණ්ඩ අතරින් 'සිම්බල්ස්' (Cymbals) සහ 'ට්‍රයන්ගල්' (Triangle) අයත් වන්නේ කුමන කාණ්ඩයටද?", "ඝන වාද්‍ය (Idiophones)", "තත වාද්‍ය (Chordophones)", "සුසිර වාද්‍ය (Aerophones)", "අවනද්ධ වාද්‍ය (Membranophones)", "ලෝහ එකිනෙක ගැටීමෙන් නාද උපදවන බැවින් මේවා ඝන වාද්‍ය ගණයට වැටේ."),
        q("ගැටබෙරයේ වම් ඇසින් සහ දකුණු ඇසින් පිටවන මූලික නාද අක්ෂර දෙකක් නිවැරදිව දැක්වෙන්නේ කවර පිළිතුරේද?", "දොං සහ තත්", "නා සහ තිං", "ස සහ රි", "දිං සහ දිග", "ගැටබෙරයේ වම් ඇසින් ගැඹුරු 'දොං' හඬද දකුණු ඇසින් 'තත්', 'ජිත්' වැනි හඬද පිටවේ."),
        q("තබ්ලාවේ වම් අතේ 'බායා' මත අත්ල තබා ඇඟිලිවලින් ගසා මැණික් කටුවෙන් ඉදිරියට තද කර උපදවන නාදය කුමක්ද?", "ගේ (Ghe) බේස් නාදය", "තා (Ta) දකුණු නාදය", "තිත් (Tit) වැසූ නාදය", "කත් (Kat) පැතලි නාදය", "මැණික් කටුව සම මත ලිස්සා හඬ වෙනස් කරමින් වැයෙන 'ගේ' නාදය තබ්ලාවට අනන්‍ය වේ."),
        q("තබ්ලාවේ දායා හා බායා යන දෙකටම එකවර පහර දීමෙන් උපදින සංයුක්ත අක්ෂරය කුමක්ද?", "ධා (Dha) හෝ ධිං (Dhin)", "නා (Na) හෝ තා (Ta)", "කේ (Ke) හෝ ගේ (Ge)", "තිරිකිට (Tirakita)", "දායා හි 'නා' සමඟ බායා හි 'ගේ' එකවර වැයීමෙන් 'ධා' ද, 'තිං' සමඟ 'ගේ' වැයීමෙන් 'ධිං' ද උපදී."),
        q("කර්ණාටක සංගීතයේ ප්‍රධාන තත වාද්‍ය භාණ්ඩයක් වන වයලීනය දකුණු ඉන්දියාවට හඳුන්වා දීමෙන් පසු සිදුවූ විශේෂත්වය කුමක්ද?", "ගමක අලංකාර වැයීමට හැකි සේ පෙරදිග සුසරට අනුවර්තනය වීම", "කර්ණාටක සංගීතයෙන් ඉවත් කිරීම", "ගජය වෙනුවට කඩිප්පු භාවිත කිරීම", "තන්තු 4 වෙනුවට 1 තන්තුවක් දැමීම", "බාලුස්වාමි දීක්ෂිතර් වැන්නවුන් වයලීනය කර්ණාටක ගායනයට අනුවර්තනය කළහ."),
        q("ගිටාරයේ ස්වරයක් වාදනය කිරීමේදී පර්දා අතර මැද කොටසේ ඇඟිල්ල තබනවා වෙනුවට කුමන තැනක තැබීම සුදුසුද?", "ඊළඟ පර්දාවට ආසන්න ඉහළ කෙළවරට සමීපව", "පර්දා ලෝහ පටිය මතම කෙළින්ම", "ශබ්ද සිදුර ඇතුළත", "තුම්බාවේ පිටුපස", "පර්දාවට ආසන්නව ඇඟිල්ල තද කිරීමෙන් බසින් (Buzz) නොමැති පැහැදිලි ස්වර හඬක් ලැබේ."),
        q("ඉන්දීය හා ශ්‍රී ලාංකේය ජන ගී වාදනයේදී වීණා හෝ සිතාර් නොමැති ගැමි පරිසරයේ ස්වර හා රිද්ම සඳහා භාවිත කළ සරල තත භාණ්ඩයක් කුමක්ද?", "එක්තාරා (ඒකතන්ත්‍රී වීණාව) / කිඳුරු වීණාව", "ග්‍රෑන්ඩ් පියානෝව", "පයිප් ඕගනය", "ටිම්පනි බෙරය", "තනි තන්තුවකින් සමන්විත සරල බවුල් හා ජන සංගීත භාණ්ඩයක් ලෙස එක්තාරා ප්‍රකටය."),
        q("පංචතූර්ය නාද පූජාවේදී 'තූර්ය' යන වචනයෙන් අදහස් කරනු ලබන්නේ කුමක්ද?", "සියලු වාද්‍ය භාණ්ඩ සමූහය", "බෙර වර්ග පමණක්", "කාන්තා ගායනය පමණක්", "නැටුම් ඇඳුම් කට්ටලය", "ආතත, විතත, විතතාතත, ඝන, සුසිර යන පස් වැදෑරුම් වාද්‍ය භාණ්ඩ තූර්ය ලෙස හැඳින්වේ."),
        q("භාණ්ඩයකින් නිකුත් වන ස්වරයක 'නාද ගුණය' (Timbre / Tone Quality) යනු කුමක්ද?", "විවිධ භාණ්ඩවල හඬ එකිනෙකින් වෙන්කර හඳුනාගත හැකි ලක්ෂණය", "ස්වරය ඉතා හයියෙන් ඇසෙන ප්‍රමාණය", "ස්වරය කොපමණ වේලාවක් පවතීද යන්න", "එම ස්වරය මන්ද්‍රද තාරද යන්න", "වයලීනය හා බන්සූරිය එකම ස්වරය වැයුවත් ඒවායේ ශබ්දය වෙනස්ව හඳුනාගන්නේ නාද ගුණය නිසාය."),
        q("වාද්‍ය භාණ්ඩයක් ප්‍රායෝගික පරීක්ෂණයකට හෝ ප්‍රසංගයකට ගෙන යාමේදී වඩාත්ම වැදගත් වන සූදානම කුමක්ද?", "භාණ්ඩය නිවැරදි ශ්‍රැතියට සුසර කර (Tune) තබාගැනීම", "භාණ්ඩයේ අලුත් තීන්ත ආලේප කිරීම", "අනෙක් භාණ්ඩවලට වඩා ශබ්දය වැඩි කිරීම", "මුලින්ම කැඩුණු තන්තු ඉවත් නොකිරීම", "සංගීත ප්‍රසංගයක මිහිරියාව රඳා පවතින්නේ සියලු භාණ්ඩ එකම ශ්‍රැතියට සුසර කර තිබීම මතය."),
        q("දේශීය හා පෙරදිග වාද්‍ය භාණ්ඩ පිළිබඳ හැදෑරීම O/L සිසුවෙකුට වැදගත් වන්නේ කුමක් නිසාද?", "භාණ්ඩවල නාද උප්පත්ති විද්‍යාව හා සංස්කෘතික අගය වටහා ගැනීමට", "භාණ්ඩ වෙළඳාම පමණක් ඉගෙනීමට", "වාද්‍ය භාණ්ඩ එකතු කර තබාගැනීමට පමණක්", "විදේශීය භාණ්ඩ ප්‍රතික්ෂේප කිරීමට", "සංගීත ශාස්ත්‍රය, නිර්මාණකරණය හා සංස්කෘතික උරුමය අවබෝධ කර ගැනීමට මෙය ඉවහල් වේ."),
        q("තබ්ලාවේ දකුණු බෙරය වන 'දායා' නිර්මාණය කිරීම සඳහා බහුලව යොදාගන්නා දැව වර්ගය කුමක්ද?", "ශීෂම් හෝ විජය දැව (Rosewood / Kheir)", "තේක්ක හෝ රබර් පතුරු", "ප්ලාස්ටික් නල", "වැල් අරළිය දඬු", "ඝන සාරයෙන් යුත් ශීෂම් හෝ බුරුත වැනි දැවයෙන් දායා බෙර කඳ නිපදවයි."),
        q("තබ්ලාවේ දායා හා බායා බෙරවල මැද පිහිටි කළු රවුම් කොටස (සියාහි) සකස් කරන්නේ කුමන ද්‍රව්‍ය මිශ්‍රණයෙන්ද?", "යකඩ කුඩු, බත් හෝ පාන්පිටි සහ කළු පැහැති සායම්", "වැලි සහ සිමෙන්ති", "මැටි සහ ලුණු කැට", "පොල්තෙල් සහ ඉටි", "බර හා කල්පැවැත්මැති සුසර නාදයක් ලැබීමට යකඩ කුඩු හා ඇලෙන පිටි මිශ්‍රණයෙන් සියාහි ගසයි."),
        q("උඩරට ගැටබෙරයේ වම් සහ දකුණු බෙර ඇස් දෙක සඳහා භාවිත කරන සම් වර්ග පිළිවෙළින් මොනවාද?", "ගව සම සහ වඳුරු සම", "මුව සම සහ තලගොයි සම", "එළු සම සහ පිඹුරු සම", "බැටළු සම සහ කුරුළු සම", "ගැටබෙරයේ වම් ඇසට ඝන ගව සමක්ද දකුණු ඇසට තුනී වඳුරු සමක්ද යොදයි."),
        q("සිංහල සාම්ප්‍රදායික පංචතූර්ය වර්ගීකරණයේදී 'තාලම්පට' අයත් වන්නේ කුමන භාණ්ඩ ගණයටද?", "ඝන වාද්‍ය භාණ්ඩ", "ආතත වාද්‍ය භාණ්ඩ", "සුසිර වාද්‍ය භාණ්ඩ", "විතත වාද්‍ය භාණ්ඩ", "ලෝහ තැටි දෙකක් එකිනෙක ගැටීමෙන් නාද උපදවන තාලම්පට ඝන වාද්‍ය ගණයට අයත් වේ."),
        q("සිතාරයේ ප්‍රධාන වාදන තන්තුව වන 'බාජ් කා තාර්' සාමාන්‍යයෙන් සුසර කරනු ලබන්නේ කුමන ස්වරයටද?", "මධ්‍යමය (ම) හෝ ෂඩ්ජයට", "ධෛවතයට (ධ)", "කෝමල රිෂභයට", "තාර නිෂාදයට", "සාම්ප්‍රදායික රවිශංකර් හා පොදු සිතාර් සුසර ක්‍රමයේදී ප්‍රධාන වාදන තන්තුව 'ම' ට සුසර වේ."),
        q("වයලීනයේ සිව්වන හා සිහින්ම තන්තුව වන E තන්තුවෙන් පහළම හා ඝනම තන්තුව දක්වා පිළිවෙළින් ස්ථානගත වන්නේ මොනවාද?", "E, A, D, G", "C, D, E, F", "G, B, D, F", "A, B, C, D", "බටහිර සම්මතය අනුව වයලීනය G - D - A - E ලෙස පංචම පරතරවලින් සුසර කෙරේ."),
        q("වයලීනයේ 'බෝ' (Bow / ගජය) හි ඇද ඇති සිහින් කෙඳි සෑදී ඇත්තේ කුමකින්ද?", "අශ්ව වල්ගයේ කෙඳිවලින්", "කපු නූල්වලින්", "වීදුරු කෙඳිවලින්", "තඹ කම්බිවලින්", "අශ්ව කෙඳි මත රොසින් ආලේප කිරීමෙන් තන්තු සමඟ මිහිරි ඝර්ෂණයක් ඇති වේ."),
        q("හොරණෑවේ ඉහළම කොටසේ සවි කරන කුඩා රීඩ් කොටස (පත) සාදාගැනීමට ශ්‍රී ලංකාවේ බහුලව යොදාගන්නේ කුමක්ද?", "වියළි තල් කොළ හෝ පන් පත", "ප්ලාස්ටික් බට", "ලෝහ තහඩු", "ගව සම් පතුරු", "පිම්බීමේදී කම්පනය වී තියුණු නාදය උපදවන පත තල් ගොබයෙන් සකසයි."),
        q("දේශීය හා භාරතීය වාද්‍ය භාණ්ඩ වර්ගීකරණයේදී 'පහතරට යක්බෙරය' වාදනය කරන්නේ කුමකින්ද?", "දෑතේ ඇඟිලි හා අත්ලෙන් පමණක්", "කඩිප්පු දෙකකින්", "දැව කූරු යුගලයකින්", "ලෝහ මිටියකින්", "යක්බෙරය ආතත ගණයට අයත් වන අතර දෑතින්ම තට්ටු කරමින් වාදනය කෙරේ."),
        q("සිංහල සාම්ප්‍රදායික 'දවුල' වාදනය කිරීමේදී වම් අතින් සහ දකුණු අතින් භාවිත කරන ක්‍රමය කුමක්ද?", "වම් අතින් කෙළින්ම සමටද දකුණු අතින් කඩිප්පුවෙන්ද ගැසීම", "දෙපසටම කඩිප්පු දෙකක් යෙදීම", "දෙපසටම අතින් පමණක් ගැසීම", "පයින් පාගා තබා ගැසීම", "දවුල විතතාතත ගණයට ඇතුළත් වන්නේ කඩිප්පුව හා අත යන දෙකම යොදන බැවිනි."),
        q("බන්සූරි බටනලාව සහ හාමෝනියමය යන දෙකම සමාන වන්නේ කුමන මූලික නාද වර්ගීකරණයට අනුවද?", "සුසිර වාද්‍ය භාණ්ඩ (වාත කම්පනයෙන් නාද උපදවන)", "තත වාද්‍ය භාණ්ඩ", "ඝන වාද්‍ය භාණ්ඩ", "අවනද්ධ වාද්‍ය භාණ්ඩ", "බටනලාවේ නළය තුළද හාමෝනියමේ රීඩ් තුළද වායු කම්පනයෙන් ස්වර උපදී."),
        q("ජපානයේ සාම්ප්‍රදායික සංගීතයේ ප්‍රකට තත වාද්‍ය භාණ්ඩයක් ලෙස ලෝක වාද්‍ය භාණ්ඩ යටතේ හඳුන්වන්නේ කුමක්ද?", "කොටෝ (Koto) හෝ ෂමිසෙන්", "සිතාරය", "තම්මැට්ටම", "රබාන", "තන්තු 13ක් සහිත දිගු තත වාද්‍ය භාණ්ඩයක් වන කොටෝ ජපන් සම්භාව්‍ය සංගීතයේ සංකේතයකි.")
    )
}
